// Uses complete role pages generated by AppearancePreferencesTest and real pagination HTML.
// Set BHEAMS_APPEARANCE_FIXTURES, BHEAMS_PAGINATION_HTML, and PLAYWRIGHT_MODULE.
const fs = require('node:fs');
const path = require('node:path');
const http = require('node:http');
const assert = require('node:assert/strict');
const { chromium } = require(process.env.PLAYWRIGHT_MODULE || 'playwright-core');
const fixtures = process.env.BHEAMS_APPEARANCE_FIXTURES;
const paginationDirectory = process.env.BHEAMS_PAGINATION_HTML;
if (!fixtures || !paginationDirectory) throw Error('Generate role-page and pagination fixtures first.');
const publicRoot = path.resolve(__dirname, '../../public');
let base;
const server = http.createServer((request, response) => {
    const pathname = new URL(request.url, base).pathname;
    const file = pathname.endsWith('.html') ? path.join(fixtures, path.basename(pathname)) : path.join(publicRoot, pathname);
    if (!fs.existsSync(file) || !fs.statSync(file).isFile()) { response.statusCode = 404; response.end(); return; }
    response.setHeader('Content-Type', file.endsWith('.html') ? 'text/html' : file.endsWith('.js') ? 'text/javascript' : file.endsWith('.css') ? 'text/css' : 'application/octet-stream');
    response.end(file.endsWith('.html') ? fs.readFileSync(file, 'utf8').replaceAll('http://localhost', base) : fs.readFileSync(file));
});

(async () => {
    await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
    base = `http://127.0.0.1:${server.address().port}`;
    const browser = await chromium.launch({ executablePath: process.env.BHEAMS_BROWSER || 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe', headless: true });
    let layouts = 0;
    try {
        for (const width of [320, 390, 768, 1440]) {
            const page = await browser.newPage({ viewport: { width, height: 1000 } });
            await page.route('**/*', route => route.request().url().startsWith(base) ? route.continue() : route.abort());
            for (const file of fs.readdirSync(fixtures).filter(file => file.endsWith('.html'))) {
                await page.goto(`${base}/${file}`);
                const originalWidth = await page.evaluate(() => document.documentElement.scrollWidth);
                await page.evaluate(() => {
                    const medicinePicker = document.getElementById('medicinePickerModal');
                    if (medicinePicker) {
                        medicinePicker.classList.add('active');
                        medicinePicker.setAttribute('aria-hidden', 'false');
                    }
                    const candidates = [...document.querySelectorAll('.pagination-container, .users-pagination, .audit-pagination, .citizen-pagination, .medicine-picker-pagination')];
                    const container = candidates.find(node => node.getBoundingClientRect().width && getComputedStyle(node).display !== 'none');
                    const host = document.createElement('div'); host.id = 'pagination-check';
                    (container || document.querySelector('.main-content') || document.querySelector('main') || document.body).append(host);
                });
                for (const theme of ['light', 'dark']) {
                    await page.evaluate(theme => {
                        document.documentElement.dataset.theme = theme;
                        document.body.classList.remove('theme-light', 'theme-dark');
                        document.body.classList.add(`theme-${theme}`);
                    }, theme);
                    for (const current of [1, 11, 21]) {
                        const html = fs.readFileSync(path.join(paginationDirectory, `bheams-pagination-${current}.html`), 'utf8');
                        await page.locator('#pagination-check').evaluate((node, html) => node.innerHTML = html, html);
                        const nav = page.locator('#pagination-check .bheams-pagination');
                        await nav.scrollIntoViewIfNeeded();
                        await page.waitForTimeout(60);
                        const result = await nav.evaluate(nav => {
                            const scroll = nav.querySelector('[data-pagination-scroll]');
                            const list = nav.querySelector('ul');
                            const active = nav.querySelector('[aria-current=page]');
                            const bounds = scroll.getBoundingClientRect();
                            const listBounds = list.getBoundingClientRect();
                            const activeBounds = active.getBoundingClientRect();
                            return {
                                rowCount: new Set([...list.children].map(item => Math.round(item.getBoundingClientRect().top))).size,
                                scrollWidth: scroll.clientWidth,
                                centered: Math.abs(listBounds.left + listBounds.width / 2 - bounds.left - bounds.width / 2) < 2,
                                fits: list.scrollWidth <= scroll.clientWidth,
                                currentVisible: activeBounds.left >= bounds.left - 1 && activeBounds.right <= bounds.right + 1,
                                activeBackground: getComputedStyle(active).backgroundColor,
                                otherBackground: getComputedStyle(list.querySelector('a') || list.firstElementChild.firstElementChild).backgroundColor,
                                summaryCenter: Math.abs(nav.querySelector('p').getBoundingClientRect().left + nav.querySelector('p').getBoundingClientRect().width / 2 - bounds.left - bounds.width / 2) < 2,
                            };
                        });
                        const label = `${file} ${width}px ${theme} page ${current}`;
                        assert.equal(result.rowCount, 1, `${label}: one button row`);
                        assert.ok(result.scrollWidth > 0, `${label}: visible pagination`);
                        if (result.fits) assert.ok(result.centered, `${label}: centered links`);
                        assert.ok(result.summaryCenter, `${label}: centered summary`);
                        assert.ok(result.currentVisible, `${label}: active page visible`);
                        assert.notEqual(result.activeBackground, result.otherBackground, `${label}: distinct active state`);
                        assert.ok(await page.evaluate(before => document.documentElement.scrollWidth <= Math.max(innerWidth, before), originalWidth), `${label}: no added page overflow`);
                        const scroll = nav.locator('[data-pagination-scroll]');
                        await scroll.evaluate(node => node.scrollLeft = 0);
                        const first = await nav.locator('li').first().boundingBox();
                        const bounds = await scroll.boundingBox();
                        assert.ok(first.x >= bounds.x - 1, `${label}: previous/first page reachable`);
                        layouts++;
                    }
                }
                if (file === 'bhw-families-show.html') {
                    for (const id of ['citizenPickerModal', 'subgroupPickerModal']) {
                        await page.locator(`#${id}`).evaluate(dialog => dialog.showModal());
                        const controls = page.locator(`#${id} .pagination-controls`);
                        const row = await controls.evaluate(node => {
                            const children = [...node.children].map(child => child.getBoundingClientRect());
                            const bounds = node.getBoundingClientRect();
                            return {
                                centers: children.map(box => box.top + box.height / 2),
                                fits: node.scrollWidth <= node.clientWidth,
                                centerOffset: Math.abs((children[0].left + children.at(-1).right) / 2 - bounds.left - bounds.width / 2),
                            };
                        });
                        assert.ok(Math.max(...row.centers) - Math.min(...row.centers) < 2, `${id} ${width}px: single client-side row`);
                        if (row.fits) assert.ok(row.centerOffset < 2, `${id} ${width}px: centered client-side controls`);
                        await page.locator(`#${id}`).evaluate(dialog => dialog.close());
                    }
                }
                if (process.env.BHEAMS_PAGINATION_SCREENSHOTS && width === 390) {
                    fs.mkdirSync(process.env.BHEAMS_PAGINATION_SCREENSHOTS, { recursive: true });
                    await page.screenshot({ path: path.join(process.env.BHEAMS_PAGINATION_SCREENSHOTS, file + '.png') });
                }
            }
            await page.close();
        }
        console.log(`${layouts} pagination layouts passed: all four roles, 320/390/768/1440px, light/dark, first/middle/last pages.`);
    } finally {
        await browser.close();
        await new Promise(resolve => server.close(resolve));
    }
})().catch(error => { console.error(error); server.close(); process.exitCode = 1; });
